(() => {
  'use strict';
  const $ = selector => document.querySelector(selector);
  const icons = {
    sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>',
    moon:'<path d="M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', chevron:'<path d="m9 5 7 7-7 7"/>',
    edit:'<path d="m15 4 5 5M4 20l5-1L20 8a2 2 0 0 0-5-5L4 14Z"/>',
    check:'<path d="m5 12 4 4L19 6"/>', lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>', plus:'<path d="M12 4v16M4 12h16"/>',
    close:'<path d="m6 6 12 12M6 18 18 6"/>', send:'<path d="m5 12 7-7 7 7m-7-7v14"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', expand:'<path d="M4 9V4h5m6 0h5v5M4 15v5h5m6 0h5v-5"/>',
    sparkle:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',
    book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H3Zm18 0h-6a3 3 0 0 0-3 3v14a3 3 0 0 1 3-3h6Z"/>'
  };
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.arrow}</svg>`;
  const escape = text => String(text).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const params = new URLSearchParams(location.search);
  const state = {view:['home','workbench','director'].includes(params.get('view'))?params.get('view'):'director', theme:params.get('theme')==='dark'?'dark':'light', step:0, complete:0, name:'白瓷精华 · 新品上市', product:'白瓷精华液', platform:'抖音 / 小红书', duration:'10 秒', brief:'一支给都市女性看的新品短片。保留白色瓶身和简洁包装，突出日常护肤的轻盈、安静与仪式感。', tone:'自然生活感', image:'assets/scene-1.jpg', referenceName:'商品参考图.jpg', approved:[false,false], mode:'full', quickKind:'image', quickRatio:'1:1', quickSize:'2K', quickTemplate:'氛围场景', quickPrompt:'保留参考图中的白色精华瓶，放在温润的浅色台面上。自然晨光，克制留白，柔和阴影，呈现安静的日常护肤氛围。', scenes:['微距靠近白色精华瓶，柔和晨光从侧面掠过，呈现磨砂质感。','镜头缓慢拉远，保留一瓶商品，浅色背景与自然光影组成安静的收尾。'], sceneDurations:['5','5'], quickResult:false};
  Object.assign(state,{boardsReady:false,clipsComposed:false,assistantDraft:'',assistantResponse:''});
  let toastTimer, lastDialogFocus;
  const stageNames=['需求','脚本与镜头','分镜审核','视频生成','交付'];
  const stageTitles=['先认识一下你的商品','让故事有一个好节奏','把每一镜，看得更清楚','确认后，让画面动起来','这一支，准备好交付了'];
  const stageDescriptions=['描述商品和期待的感觉，其余的我们一步步来。','先确认画面与时长，再进入分镜创作。','逐镜核对商品与构图，通过后再生成视频。','选择交付方式，核对本次镜头与费用。','查看示例成片，也可以把这次节奏留下来。'];
  function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
  function syncUrl(){const url=new URL(location.href);url.searchParams.set('view',state.view);url.searchParams.set('theme',state.theme);history.replaceState(null,'',url);}
  function applyTheme(){document.documentElement.dataset.theme=state.theme;$('.theme-toggle').innerHTML=icon(state.theme==='light'?'moon':'sun');syncUrl();}
  function navigate(view){capture();state.view=view;syncUrl();$('#companion').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'});}
  function capture(){const values={product:'product-name',brief:'brief',platform:'platform',duration:'target-duration',quickPrompt:'quick-prompt',assistantDraft:'assistant-text'};Object.entries(values).forEach(([key,id])=>{const el=$('#'+id);if(el)state[key]=el.value;});document.querySelectorAll('[data-scene]').forEach(el=>state.scenes[Number(el.dataset.scene)]=el.value);document.querySelectorAll('[data-duration]').forEach(el=>state.sceneDurations[Number(el.dataset.duration)]=el.value);}
  function openDialog(title,body,actionText,onAction){lastDialogFocus=document.activeElement;const dialog=$('#dialog');dialog.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}<div class="dialog-actions"><button class="secondary" data-dismiss>返回修改</button><button class="primary" id="dialog-confirm">${actionText}${icon('arrow')}</button></div>`;dialog.querySelector('[data-dismiss]').onclick=()=>dialog.close();$('#dialog-confirm').onclick=()=>{const result=onAction?.();if(result!==false)dialog.close();};dialog.showModal();}
  $('#dialog').addEventListener('close',()=>{if(lastDialogFocus?.isConnected)lastDialogFocus.focus();});
  function reference(){return `<div class="reference-box"><div class="reference-well"><img src="${escape(state.image)}" alt="白色磨砂精华瓶商品参考图"><span class="photo-caption">PRODUCT REFERENCE</span><button class="photo-edit" data-action="upload" aria-label="更换商品参考图">${icon('edit')}</button></div><div class="reference-detail"><strong>${escape(state.referenceName)}</strong><span>仅在原型中预览</span></div></div>`;}
  function briefStep(){return `<div class="brief-grid">${reference()}<div><label class="form-field"><span>商品叫什么？</span><input id="product-name" value="${escape(state.product)}" maxlength="60" placeholder="如：白瓷精华液"></label><div class="field-row"><label class="form-field"><span>准备发在哪里</span><select id="platform">${['抖音 / 小红书','淘宝 / 天猫','品牌自媒体'].map(x=>`<option ${x===state.platform?'selected':''}>${x}</option>`).join('')}</select></label><label class="form-field"><span>期待的总片长</span><select id="target-duration">${['10 秒','15 秒','20 秒'].map(x=>`<option ${x===state.duration?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="form-field"><span>想让人记住什么？<small>创作意图</small></span><textarea id="brief" rows="4">${escape(state.brief)}</textarea></label></div></div><p class="purpose-label">给这支短片选一种感觉</p><div class="choice-row">${['自然生活感','极简棚拍','温暖治愈','自由描述'].map(x=>`<button class="chip ${state.tone===x?'selected':''}" aria-pressed="${state.tone===x}" data-tone="${x}">${x}</button>`).join('')}</div>`;}
  function scriptStep(){return `<div class="script-summary"><div class="eyebrow">CREATIVE DIRECTION · 示例脚本</div><p>从质感走进日常。用两个克制的镜头，让商品成为画面的中心，也让光线成为故事的线索。</p></div>${state.scenes.map((s,i)=>`<div class="shot-row"><span class="shot-num">0${i+1}</span><label>${i===0?'质感开场':'留白收尾'}<textarea data-scene="${i}" rows="2">${escape(s)}</textarea></label><label>时长<select data-duration="${i}">${[3,4,5,6,8,10].map(n=>`<option value="${n}" ${state.sceneDurations[i]===String(n)?'selected':''}>${n} 秒</option>`).join('')}</select></label></div>`).join('')}<p class="tiny-note">可直接编辑每一镜。确认只推进原型步骤，不调用文本模型。</p>`;}
  function storyboardStep(){if(!state.boardsReady)return `<div class="script-summary"><div class="eyebrow">BEFORE THE FIRST FRAME</div><p>脚本已确认。接下来，为每个镜头准备一张分镜图，看看想法在画面里是什么样子。</p></div><table class="quote-table"><thead><tr><th>待生成分镜</th><th>示例规格</th><th>示例费用</th></tr></thead><tbody><tr><td>镜头 01 · 质感开场</td><td>2K · 1:1</td><td>¥ 0.12</td></tr><tr><td>镜头 02 · 留白收尾</td><td>2K · 1:1</td><td>¥ 0.12</td></tr></tbody></table><div class="quote-total"><div><small>2 张分镜 · 参考商品图</small><p>图片生成示例合计</p></div><strong>¥ 0.24</strong></div><p class="tiny-note">这是原型报价示例。主动确认后才展示预置分镜图片，不执行真实生成。</p>`;return `<div class="story-grid">${[1,2].map((n,i)=>`<article class="story-card"><img src="assets/scene-${n}.jpg" alt="镜头 ${n} 示例分镜" loading="eager"><div class="story-meta"><header><strong>镜头 0${n}</strong><span>${state.sceneDurations[i]} 秒</span></header><p>${i===0?'近景 · 磨砂质感':'中景 · 光影留白'} · 示例 v1</p><button class="check-button ${state.approved[i]?'approved':''}" data-approve="${i}" aria-pressed="${state.approved[i]}">${state.approved[i]?'✓ 已核对这张示例':'○ 核对并通过'}</button></div></article>`).join('')}</div><p class="tiny-note">请检查商品数量、瓶身比例与包装细节。这里展示已有示例素材。</p>`;}
  function videoStep(){return `<div class="mode-options">${[['full','完整视频','所有镜头完成后，按顺序合成一支短片。'],['clips','独立片段','逐镜保留视频，方便后续剪辑与组合。']].map(([v,t,d])=>`<button class="mode-option ${state.mode===v?'selected':''}" data-mode="${v}" aria-pressed="${state.mode===v}"><span class="radio"></span><span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div><table class="quote-table"><thead><tr><th>本次镜头</th><th>输出规格</th><th>示例费用</th></tr></thead><tbody>${state.scenes.map((_,i)=>`<tr><td>镜头 0${i+1} · ${state.sceneDurations[i]} 秒</td><td>9:16 · 720p</td><td>¥ 0.44</td></tr>`).join('')}</tbody></table><div class="quote-total"><div><small>2 个镜头 · 计划 ${state.sceneDurations.reduce((sum,n)=>sum+Number(n),0)} 秒</small><p>本次示例合计</p></div><strong>¥ 0.88</strong></div><p class="tiny-note">演示金额，不是实时模型报价；点击确认仅进入示例交付页。</p>`;}
  function sampleFilm(){return `<div class="film-preview"><video controls playsinline preload="metadata" poster="assets/scene-1.jpg" src="assets/sample-film.mp4" aria-label="示例成片预览"></video><div class="film-copy"><span class="success-tag">✓ 预置完整成片 · 10.08 秒</span><h3>一份安静的，<br>日常仪式感。</h3><p>完整短片 · 9:16 · 示例 v1<br>当前播放的是预置示例视频，<br>没有执行本次生成或拼接。</p><div class="film-actions"><a class="secondary" href="assets/sample-film.mp4" download="物料间-示例成片.mp4">${icon('download')}下载示例成片</a><button class="secondary" data-action="save-template">${icon('book')}保存节奏模板</button></div></div></div>`;}
  function deliveryStep(){if(state.mode==='full')return sampleFilm();return `<div class="delivery-clips">${[1,2].map(n=>`<article class="delivery-clip"><video controls playsinline preload="metadata" poster="assets/scene-${n}.jpg" src="assets/clip-${n}.mp4" aria-label="镜头 ${n} 独立示例片段"></video><div class="clip-meta"><strong>镜头 0${n}</strong><span>示例实测 5.04 秒</span><a class="secondary" href="assets/clip-${n}.mp4" download="物料间-示例片段-${n}.mp4">${icon('download')}下载这段示例</a></div></article>`).join('')}</div><div class="clip-compose"><div><strong>两段素材，各自保留。</strong><p>想看连起来的效果？确认后才展示合成示例。</p></div><button class="secondary" data-action="compose-clips" ${state.clipsComposed?'disabled':''}>${state.clipsComposed?'合成示例已展开':'查看合成示例'}${icon('arrow')}</button></div><p class="tiny-note">片段是预置素材，示例实测时长与当前计划时长分别展示；未生成或拼接新文件。</p>${state.clipsComposed?`<div class="composed-sample"><p class="purpose-label">已确认查看 · 预置合成示例</p>${sampleFilm()}</div>`:'<div class="film-actions"><button class="secondary" data-action="save-template">'+icon('book')+'保存节奏模板</button></div>'}`;}
  function footer(){const texts=['确认需求，进入脚本','确认脚本，进入分镜',state.boardsReady?'确认分镜，进入视频':'查看分镜生成确认','确认示例，查看交付','完成这次原型体验'];return `<div class="step-footer"><span class="footer-note">${icon('lock')}${state.step===4?'示例文件，不是本次生成产物':'只确认当前步骤，由你决定下一步'}</span><button class="primary" data-action="advance" ${state.step===2&&state.boardsReady&&!state.approved.every(Boolean)?'disabled':''}>${texts[state.step]}${icon('arrow')}</button></div>`;}
  function director(){const visibleStages=stageNames.slice(0,state.complete+1);return `<div class="director-shell"><section class="director-main"><div class="breadcrumb"><button data-view="home">我的项目</button><span>/</span><span>${escape(state.name)}</span></div><div class="page-intro"><div><div class="eyebrow">A LITTLE DIRECTION, A BETTER STORY</div><h1>${state.step===0?'好作品，从说清商品开始。':state.step===4?'让这次创作，好好收尾。':'一次只做好，眼前这一步。'}</h1><p>${state.step===0?'不必准备完整方案。有一个商品，一个想法，就够了。':'每一次确认，都让你离想要的作品更近一点。'}</p></div><span class="project-token"><i class="live-dot"></i> 当前浏览器演示</span></div><div class="progress-rail" aria-label="创作进度">${visibleStages.map((n,i)=>`${i?'<span class="connector"></span>':''}<button class="progress-item ${i===state.step?'current':i<state.complete?'complete':''}" ${i===state.step?'aria-current="step"':''} data-step="${i}"><span class="number">${i<state.complete?'✓':i+1}</span><span>${n}</span></button>`).join('')}</div>${state.complete>0?`<div class="history">${stageNames.slice(0,state.complete).filter((_,i)=>i!==state.step).map(n=>{const i=stageNames.indexOf(n);return `<div class="history-item"><div><span class="check">✓</span>${n}<small>${i===0?escape(state.product)+' · '+escape(state.tone):i===1?'2 镜 · '+state.sceneDurations.reduce((s,n)=>s+Number(n),0)+' 秒':i===2?'2 张示例已核对':'示例范围已确认'}</small></div><button data-history="${i}">回看与修改 ↗</button></div>`;}).join('')}</div>`:''}<article class="step-card"><header class="step-top"><div><div class="step-label">STEP 0${state.step+1} / ${stageNames[state.step]}</div><h2>${stageTitles[state.step]}</h2><p>${stageDescriptions[state.step]}</p></div><span class="step-counter">0${state.step+1} — 05</span></header><div class="step-body">${[briefStep,scriptStep,storyboardStep,videoStep,deliveryStep][state.step]()}</div>${footer()}</article><div class="under-note"><span>创作不需要一步到位。<br class="mobile-break">你随时可以回看已完成的步骤。</span><button data-action="restart">重新体验这个项目 ↗</button></div></section><div aria-hidden="true"></div></div>`;}
  function home(){return `<div class="home-shell"><section class="home-hero"><div><div class="eyebrow">YOUR SMALL, EVERYDAY CREATIVE SPACE</div><h1>把好商品，<br>变成<em>好内容。</em></h1><p>从一张商品图，到一支有节奏的短片。<br>在物料间，把想法慢慢做成作品。</p><div class="home-secondary"><button class="primary" data-action="new-project">开始一个新项目${icon('plus')}</button><button class="text-button" data-view="workbench">直接做一张图</button></div></div><div class="home-visual"><img src="assets/scene-2.jpg" alt="白色精华液的柔和光影示例"><div class="visual-stamp"><strong>Made</strong>with a little care</div><div class="visual-caption"><span>A QUIET MOMENT, WELL MADE.</span><span>物料间 / 01</span></div></div></section><div class="home-titlebar"><h2>接着上次的想法</h2><span>3 个示例项目</span></div><div class="project-list">${[['白瓷精华 · 新品上市','2 镜短片 / 自然生活感','待确认创作需求','今天','1'],['一束晨光 · 场景图','商品图片 / 极简光影','示例素材可回看','昨天','2'],['白瓷 · 质感预告','短片 / 10 秒','示例交付','10 月 24 日','1']].map(([n,d,s,t,img],i)=>`<button class="project-row" data-project="${i}"><img src="assets/scene-${img}.jpg" alt="${n}"><div><strong>${n}</strong><p>${d}</p></div><span class="project-status">${s}</span><time>${t}</time>${icon('arrow')}</button>`).join('')}</div></div>`;}
  function workbench(){return `<div class="workbench-shell"><div class="workbench-title"><div><div class="eyebrow">MAKE SOMETHING, RIGHT HERE</div><h1>一个想法，即刻开始。</h1><p>选一张参考图，写下描述。简单的创作，就留在这里。</p></div><button class="secondary" data-view="director">试试导演台 ↗</button></div><div class="workbench-grid"><section class="quick-card" aria-label="快捷创作"><div class="quick-tabs">${[['image','生图'],['video','生视频']].map(([v,t])=>`<button data-quick-kind="${v}" class="${state.quickKind===v?'selected':''}" aria-pressed="${state.quickKind===v}">${t}</button>`).join('')}</div><div class="template-choice">${(state.quickKind==='image'?['白底商品','氛围场景','自由创作']:['轻推近','缓慢环绕','自由运镜']).map(t=>`<button class="chip ${state.quickTemplate===t?'selected':''}" data-quick-template="${t}">${t}</button>`).join('')}</div><button class="quick-reference" data-action="upload"> <img src="${escape(state.image)}" alt="已选参考图"><span><strong>${state.quickKind==='image'?'商品参考图':'视频首帧图'}</strong><small>点击更换 · 仅在本地预览</small></span>${icon('upload')}</button><label class="form-field"><span>想怎么呈现它？</span><textarea id="quick-prompt" rows="5">${escape(state.quickPrompt)}</textarea></label><div class="prompt-toolbar"><span>描述越具体，表达越清楚</span><button class="polish-button" data-action="polish">✳ 帮我润色</button></div><div class="quick-label">画面比例</div><div class="choice-row">${(state.quickKind==='image'?['1:1','3:4','9:16','16:9']:['1:1','9:16','16:9']).map(t=>`<button class="chip ${state.quickRatio===t?'selected':''}" data-ratio="${t}">${t}</button>`).join('')}</div><div class="quick-label">${state.quickKind==='image'?'输出清晰度':'视频规格'}</div><div class="choice-row">${(state.quickKind==='image'?['1K','2K']:['720p · 5 秒','720p · 10 秒']).map(t=>`<button class="chip ${state.quickSize===t?'selected':''}" data-size="${t}">${t}</button>`).join('')}</div><button class="primary" data-action="quick-generate">预览生成确认${icon('arrow')}</button><p class="field-hint" style="text-align:center;margin-top:10px">展示示例确认，不会调用任何模型</p></section><section aria-label="创作结果"><div class="results-heading"><h2>${state.quickResult?'本次演示结果':'给你一点灵感'}</h2><span>预置示例 · 非实时生成</span></div>${state.quickKind==='image'?`<div class="quick-results">${[1,2].map((n,i)=>`<figure class="quick-result"><img src="assets/scene-${n}.jpg" alt="${i?'光影场景':'白底商品'}示例"><button aria-label="放大查看示例 ${n}" data-preview="${n}">${icon('expand')}</button><figcaption>${i?'光影与留白':'让质感被看见'}<small>示例 ${String(n).padStart(2,'0')}</small></figcaption></figure>`).join('')}</div>`:'<video class="workbench-video" controls playsinline preload="metadata" poster="assets/scene-1.jpg" src="assets/sample-film.mp4" aria-label="预置视频示例"></video>'}<p class="preview-caption">灵感可以借鉴，商品事实需要你来确认。<br>这里的画面用于对比界面效果，不代表当前参数的生成结果。</p></section></div></div>`;}
  function companion(){const intros=[['我会陪你把这支短片一点点想清楚。','现在先告诉我：商品是什么，以及你希望观众记住什么。'],['好的，先给故事一点节奏。','你可以修改每一镜，也可以先看看这个两镜示例。'],['接下来，把注意力留给画面。','检查每张图中的商品数量、形状和包装，逐张通过。'],['快到了，最后再核对一次。','完整短片和独立片段都可以选择，费用需要你主动确认。'],['作品可以结束，灵感可以留下。','把这次镜头节奏存成模板，下次从新的商品重新开始。']];const intro=state.view==='workbench'?['需要一点文字上的帮助？','快捷台只润色提示词，复杂的创作可以交给导演台。']:intros[state.step];$('#companion').innerHTML=`<div class="companion-heading"><div class="assistant-identity"><span class="assistant-symbol">✳</span><div><div class="assistant-name">你的创作搭子</div><div class="assistant-sub">每一步，刚刚好的帮助</div></div></div><button class="icon-button close-assistant" aria-label="关闭助手">${icon('close')}</button></div><div class="assistant-message"><p>${intro[0]}</p><p class="muted">${intro[1]}</p></div><div class="suggestion-list"><button class="suggestion" data-suggestion="style">帮我找到适合的风格 <span>↗</span></button><button class="suggestion" data-suggestion="brief">我还没有完整的想法 <span>↗</span></button></div><div id="assistant-output"></div><form class="assistant-input" id="assistant-form"><label class="sr-only" for="assistant-text">向创作助手提问</label><textarea id="assistant-text" rows="2" placeholder="聊聊你的想法…">${escape(state.assistantDraft)}</textarea><button aria-label="发送示例消息" type="submit">${icon('send')}</button></form><p class="assistant-footer">示例对话 · 不调用 AI · 由你确认后采用</p><div class="assistant-placeholder">${icon('book')}<span>好的创作不赶时间。<br>你可以随时停下来，回看和调整。</span></div>`;$('#assistant-form').onsubmit=e=>{e.preventDefault();const value=$('#assistant-text').value.trim();if(!value)return;$('#assistant-text').value='';state.assistantDraft='';respond('示例回应：可以先以「商品质感 + 柔和光线」作为方向。建议只描述已知商品事实，给画面留一些呼吸感。');};$('#assistant-text').oninput=event=>{state.assistantDraft=event.target.value;};paintAssistantResponse();$('.close-assistant').onclick=()=>$('#companion').classList.remove('open');}
  function respond(text){state.assistantResponse=text;paintAssistantResponse();}
  function paintAssistantResponse(){if(!state.assistantResponse)return;const text=state.assistantResponse;$('#assistant-output').innerHTML=`<div class="assistant-response"><p>${escape(text)}</p><button id="adopt-suggestion">采用这条示例建议</button></div>`;$('#adopt-suggestion').onclick=()=>{capture();if(state.view==='workbench'){state.quickPrompt+=' 柔和侧光，保留商品原有形态，构图克制留白。';}else if(state.step===0){state.tone='自然生活感';state.brief+=' 以柔和侧光呈现商品质感，构图克制留白。';}else{notify('这条示例建议已记在对话中。请回到对应步骤手工编辑。');return;}render();notify('已写入当前原型输入，尚未执行保存或生成。');};}
  function render(){const assistantInput=$('#assistant-text');if(assistantInput)state.assistantDraft=assistantInput.value;document.querySelectorAll('.topbar [data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===state.view);if(el.dataset.view===state.view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#app').innerHTML=state.view==='home'?home():state.view==='workbench'?workbench():director();$('#companion').style.visibility=state.view==='director'?'visible':'hidden';$('#assistant-open').style.display=state.view==='home'?'none':'';if(state.view==='workbench')$('#companion').style.visibility='visible';if(state.view==='workbench'&&innerWidth>850)$('#companion').style.display='none';else $('#companion').style.display='';companion();document.title=`物料间 · ${state.view==='director'?'轻量导演台':state.view==='home'?'项目首页':'快捷工作台'}`;}
  function changeStep(index,editing){capture();if(index>state.complete)return;if(editing&&index<state.complete){openDialog('回到这一步调整？','<p>输入会保留，需要从这一步重新确认。预置素材不会被修改，也不会重新调用模型。</p>','回到这一步',()=>{state.step=index;state.complete=index;if(index<=2){state.approved=[false,false];state.boardsReady=false;}state.clipsComposed=false;render();window.scrollTo({top:120,behavior:'smooth'});});}else{state.step=index;render();}}
  function advance(){capture();if(state.step===0&&(!state.product.trim()||!state.brief.trim())){notify('请先填写商品名称和创作意图。');$('#product-name').focus();return;}if(state.step===1&&state.scenes.some(x=>!x.trim())){notify('请填写每一镜的画面描述。');return;}if(state.step===2&&!state.boardsReady){openDialog('确认分镜图片生成','<p>为两个已确认镜头准备分镜图。此处只演示报价与确认，不调用图片模型。</p><div class="confirm-detail"><span>分镜数量</span>　2 张<br><span>示例规格</span>　2K · 1:1<br><span>演示金额</span>　¥ 0.24<br><span>真实调用</span>　0 次 · 不产生费用</div>','确认并展示示例分镜',()=>{state.boardsReady=true;state.approved=[false,false];render();notify('已展示预置分镜，请逐张核对。未执行生成。');});return;}if(state.step===2&&!state.approved.every(Boolean))return;if(state.step===3){if(!state.boardsReady||!state.approved.every(Boolean)){notify('请先回到分镜步骤，确认图片并逐张审核。');return;}openDialog('确认本次示例范围',`<p>2 个镜头，${state.mode==='full'?'按顺序交付完整视频':'交付独立片段'}。这里只演示确认流程。</p><div class="confirm-detail"><span>画面规格</span>　9:16 · 720p<br><span>演示合计</span>　¥ 0.88<br><span>真实调用</span>　0 次 · 不产生费用</div>`,'确认并查看示例',()=>{state.complete=4;state.step=4;state.clipsComposed=false;render();window.scrollTo({top:120,behavior:'smooth'});});return;}if(state.step===4){navigate('home');notify('原型体验已完成。你可以再选一个示例项目。');return;}state.complete=Math.max(state.complete,state.step+1);state.step++;render();window.scrollTo({top:120,behavior:'smooth'});}
  document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b||b.disabled)return;capture();if(b.dataset.view){event.preventDefault();navigate(b.dataset.view);return;}if(b.dataset.step!==undefined){changeStep(Number(b.dataset.step),Number(b.dataset.step)<state.complete);return;}if(b.dataset.history!==undefined){changeStep(Number(b.dataset.history),true);return;}if(b.dataset.tone){capture();state.tone=b.dataset.tone;render();return;}if(b.dataset.approve!==undefined){state.approved[Number(b.dataset.approve)]=!state.approved[Number(b.dataset.approve)];render();return;}if(b.dataset.mode){state.mode=b.dataset.mode;render();return;}if(b.dataset.project!==undefined){const n=Number(b.dataset.project);state.name=n===2?'白瓷 · 质感预告':'白瓷精华 · 新品上市';state.step=n===2?4:0;state.complete=n===2?4:0;state.mode='full';state.boardsReady=n===2;state.clipsComposed=false;n===1?navigate('workbench'):navigate('director');return;}if(b.dataset.quickKind){capture();state.quickKind=b.dataset.quickKind;if(state.quickKind==='video'&&state.quickRatio==='3:4'){state.quickRatio='9:16';notify('视频示例支持 1:1、9:16、16:9，已切换为 9:16。');}state.quickResult=false;state.quickSize=state.quickKind==='image'?'2K':'720p · 5 秒';state.quickTemplate=state.quickKind==='image'?'氛围场景':'轻推近';render();return;}if(b.dataset.quickTemplate){capture();state.quickTemplate=b.dataset.quickTemplate;render();return;}if(b.dataset.ratio){capture();state.quickRatio=b.dataset.ratio;render();return;}if(b.dataset.size){capture();state.quickSize=b.dataset.size;render();return;}if(b.dataset.suggestion){respond(b.dataset.suggestion==='style'?'示例建议：白色磨砂瓶适合自然侧光与温暖的浅色背景。保留真实包装和商品数量，把重点放在质感。':'示例建议：从「给谁看、商品是什么、希望留下什么感受」开始。现在不需要写完整脚本。');return;}if(b.dataset.preview){openDialog('预置示例预览',`<p>用于界面比较，不代表本次生成结果。</p><img class="full-image" src="assets/scene-${Number(b.dataset.preview)}.jpg" alt="放大的商品示例">`,'看好了');return;}switch(b.dataset.action){case'advance':advance();break;case'upload':$('#reference-file').click();break;case'restart':capture();openDialog('重新体验这个项目','<p>这会重置原型步骤；当前演示输入仍会保留。</p>','重新开始',()=>{state.complete=0;state.step=0;state.approved=[false,false];state.boardsReady=false;state.clipsComposed=false;render();});break;case'new-project':openDialog('一个新想法，从这里开始','<p>给你的示例项目起个名字。</p><label class="form-field"><span>项目名称</span><input id="new-name" placeholder="如：秋季新品 · 温暖日常" value="白瓷精华 · 新的创意"></label>','进入导演台',()=>{const v=$('#new-name').value.trim();if(!v){$('#new-name').focus();return false;}state.name=v;state.step=0;state.complete=0;state.approved=[false,false];state.boardsReady=false;state.clipsComposed=false;navigate('director');});break;case'compose-clips':openDialog('确认查看合成示例','<p>按镜头 01 → 镜头 02 的顺序展示预置合成示例。两个独立片段各为 5.04 秒，合成示例为 10.08 秒；不生成或拼接新文件。</p>','确认并查看合成示例',()=>{state.clipsComposed=true;render();notify('已展开预置合成示例，两个独立片段仍然保留。');});break;case'save-template':openDialog('留住这次创作的节奏','<p>只保留镜头结构、时长与运镜。商品资料和参考图不会进入模板。</p><label class="form-field"><span>模板名称</span><input id="template-name" value="质感开场 · 留白收尾"></label>','在原型中记下',()=>{if(!$('#template-name').value.trim())return false;notify('已记录示例名称；未写入真实模板库。');});break;case'polish':capture();openDialog('一点润色，保留你的意思',`<p>下面是预设的润色示例，不是 AI 实时回复。</p><div class="confirm-detail">保留参考图中的白色精华瓶与真实包装。柔和晨光从侧面落下，以温润的浅色台面承托商品，干净背景，细腻阴影，克制留白。</div>`,'采用示例文字',()=>{state.quickPrompt='保留参考图中的白色精华瓶与真实包装。柔和晨光从侧面落下，以温润的浅色台面承托商品，干净背景，细腻阴影，克制留白。';render();notify('已采用润色示例，未调用 AI。');});break;case'quick-generate':capture();if(!state.quickPrompt.trim()){notify('请先写下你的创作描述。');return;}openDialog('看看这次创作设置',`<p>确认后展示预置${state.quickKind==='image'?'图片':'视频'}，没有真实生成请求。</p><div class="confirm-detail"><span>输出类型</span>　${state.quickKind==='image'?'商品图片':'商品视频'}<br><span>画面规格</span>　${escape(state.quickRatio)} · ${escape(state.quickSize)}<br><span>调用费用</span>　¥ 0 · 交互演示</div>`,'确认，展示示例',()=>{state.quickResult=true;render();notify('已展示预置示例，没有执行生成。');});break;}});
  $('.theme-toggle').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';applyTheme();};
  $('#assistant-open').onclick=()=>{$('#companion').style.display='';$('#companion').style.visibility='visible';$('#companion').classList.add('open');$('#assistant-text').focus();};
  $('#reference-file').onchange=event=>{const file=event.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return notify('请选择图片文件。');if(file.size>10*1024*1024)return notify('原型参考图请控制在 10 MB 以内。');capture();state.image=URL.createObjectURL(file);state.referenceName=file.name;render();notify('图片仅在当前浏览器预览，没有上传。');event.target.value='';};
  addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);state.view=['home','workbench','director'].includes(p.get('view'))?p.get('view'):'director';state.theme=p.get('theme')==='dark'?'dark':'light';applyTheme();render();});
  applyTheme();render();
})();
